// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *BankAccountLedgerEntry) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, BankAccountLedgerEntryTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range bankAccountLedgerEntrySIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, BankAccountLedgerEntryTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: BankAccountLedgerEntryTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, BankAccountLedgerEntryTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

